import sys
from pathlib import Path
from livingproof_sim_mujoco.cli import parser

content = (
    "# Command reference\n\nGenerated by `task docs`; do not edit by hand.\n\n```text\n"
    + parser().format_help()
    + "```\n"
)
path = Path("docs/command.md")
if "--check" in sys.argv:
    if not path.exists() or path.read_text() != content:
        raise SystemExit("Command reference is stale. Run task docs.")
else:
    path.write_text(content)
